trial.program_source:
def transform(grid):
    out=[row[:] for row in grid]
    colors=sorted({v for row in grid for v in row if v not in (0,1)})
    if not colors: return out
    color=colors[0]
    for r in range(1,len(out)):
        for c in range(len(out[0])):
            if out[r][c]==1 and out[r-1][c]==color:
                out[r][c]=color
    return out

